import type { CartLine } from '#shared/types/cart'
import { findProduct } from '#server/utils/db'
import { computeQuote } from '#server/utils/quote'

export interface OrderLine {
  slug: string
  qty: number
  name: string
}

export interface Order {
  id: string
  subtotal: string
  discount: string
  total: string
  lines: OrderLine[]
}

const orders: Order[] = []
let nextId = 1

export function saveOrder(lines: CartLine[], code?: string): Order {
  const id = String(nextId++)
  const orderLines = lines.map(line => {
    const product = findProduct(line.slug)
    return {
      slug: line.slug,
      qty: line.qty,
      name: product?.name ?? line.slug,
    }
  })
  const quote = computeQuote(lines, code)
  const order: Order = {
    id,
    ...quote,
    lines: orderLines,
  }
  orders.push(order)
  return order
}

export function findOrder(id: string): Order | undefined {
  return orders.find(o => o.id === id)
}

import type { CartLine } from '#shared/types/cart'
import { defineEventHandler, readBody } from 'h3'
import { saveOrder } from '#server/utils/orders'

export default defineEventHandler(async (event) => {
  const body = await readBody<{ lines?: CartLine[], code?: string }>(event)
  const order = saveOrder(body?.lines ?? [], body?.code)
  return order
})

import { createError, defineEventHandler, getRouterParam } from 'h3'
import { findOrder } from '#server/utils/orders'

export default defineEventHandler((event) => {
  const id = getRouterParam(event, 'id') ?? ''
  const order = findOrder(id)
  if (!order) {
    throw createError({ statusCode: 404, statusMessage: 'Order not found' })
  }
  return order
})

